import {getDocument,GlobalWorkerOptions} from './vendor/pdf.min.mjs';
GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;
const docs=new Map();let generation=0;
function rgb(variable){const el=document.createElement('span');el.style.color=`var(${variable})`;document.body.append(el);const result=getComputedStyle(el).color.match(/[\d.]+/g).slice(0,3).map(Number);el.remove();return result}
async function paint(){const canvases=[...document.querySelectorAll('.owner-pdf-canvas')];if(!canvases.length)return;const token=++generation,paper=rgb('--panel'),ink=rgb('--ink');await Promise.all(canvases.map(async canvas=>{const status=canvas.previousElementSibling;try{const url=canvas.dataset.pdf;if(!docs.has(url)){if(docs.size>2){const [key,value]=docs.entries().next().value;docs.delete(key);value.then(d=>d.destroy())}docs.set(url,getDocument(url).promise.catch(e=>{docs.delete(url);throw e}))}const doc=await docs.get(url),page=await doc.getPage(Number(canvas.dataset.page));if(token!==generation||!canvas.isConnected)return;const width=Math.max(220,canvas.parentElement.clientWidth-24),ratio=Math.min(2,devicePixelRatio||1),base=page.getViewport({scale:1}),vp=page.getViewport({scale:width/base.width*ratio}),offscreen=document.createElement('canvas');offscreen.width=vp.width;offscreen.height=vp.height;const ctx=offscreen.getContext('2d',{willReadFrequently:true});await page.render({canvasContext:ctx,viewport:vp}).promise;if(token!==generation||!canvas.isConnected)return;const image=ctx.getImageData(0,0,offscreen.width,offscreen.height),p=image.data;for(let i=0;i<p.length;i+=4){const light=(.2126*p[i]+.7152*p[i+1]+.0722*p[i+2])/255;for(let c=0;c<3;c++)p[i+c]=Math.round(ink[c]+(paper[c]-ink[c])*light)}canvas.width=offscreen.width;canvas.height=offscreen.height;canvas.getContext('2d').putImageData(image,0,0);status.hidden=true}catch{status.textContent=document.documentElement.lang==='bn'?'পাতাটি খুলতে সমস্যা হয়েছে। মূল ফাইল থেকে পড়ুন।':'Unable to render this page. Open the original file below.'}}))}
document.addEventListener('nihongo:pages',paint);document.addEventListener('nihongo:render',paint);new MutationObserver(paint).observe(document.body,{attributes:true,attributeFilter:['class']});let resize;addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(paint,150)});paint();
document.addEventListener('click',async event=>{const source=event.target.closest?.('.owner-pdf-canvas');if(!source)return;const dialog=document.createElement('dialog');dialog.className='owner-page-zoom';dialog.setAttribute('aria-label',source.getAttribute('aria-label'));const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Close enlarged page');const canvas=document.createElement('canvas');canvas.width=source.width;canvas.height=source.height;canvas.getContext('2d').drawImage(source,0,0);dialog.append(close,canvas);document.body.append(dialog);close.onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();close.focus()});
